1051: func (s *Service) maybeAutoStartReviewRound(ctx *axi.Context, db *store.DB, home string, project store.Project, change store.Task) (bool, error) {
1052: 	plan, err := change.AdmittedPlan()
1053: 	if err != nil {
1054: 		return false, admittedPlanFailure(err)
1055: 	}
1056: 	parallel := plan != nil && plan.ValidationLoops != nil && plan.ValidationLoops.ReviewParallel == "greenhouse"
1057: 	if !parallel && !autoStartReviewLoop(plan) {
1058: 		return false, nil
1059: 	}
1060: 	targets, err := changeCandidateTargets(ctx.Context, db, project, change)
1061: 	if err != nil {
1062: 		return false, err
1063: 	}
1064: 	if project.IsWorkspace() {
1065: 		taskRepos, err := db.TaskRepos(ctx.Context, change.ID)
1066: 		if err != nil {
1067: 			return false, err
1068: 		}
1069: 		gated := make(map[string]string, len(taskRepos))
1070: 		for _, repo := range taskRepos {
1071: 			gated[repo.Repo] = repo.GatedSHA
1072: 		}
1073: 		for _, target := range targets {
1074: 			if gated[target.Repository] == "" || gated[target.Repository] != target.Commit {
1075: 				return false, nil
1076: 			}
1077: 		}
1078: 	} else if len(targets) != 1 || change.GatedSHA == "" || targets[0].Commit != change.GatedSHA {
1079: 		return false, nil
1080: 	}
1081: 	if !autoStartReviewLoop(plan) {
1082: 		if parallel {
1083: 			if err := s.startParallelGreenhouseReviews(ctx.Context, db, home, project, change, targets); err != nil {
1084: 				return false, err
1085: 			}
1086: 		}
1087: 		return false, nil
1088: 	}
1089: 	if covered, err := db.ReviewTargetsCovered(ctx.Context, change.ID, targets); err != nil || covered {
1090: 		return false, err
1091: 	}
1092: 	profile, err := s.autoStartReviewProfile(ctx.Context, project, home)
1093: 	if err == nil {
1094: 		err = s.startReviewRound(ctx, db, home, project, change, profile, "")
1095: 	}
1096: 	if failure, unavailable := autoStartReviewerUnavailable(err); unavailable {
1097: 		if noticeErr := recordAutoStartReviewerReadiness(ctx.Context, db, project, change, targets, failure); noticeErr != nil {
1098: 			return false, noticeErr
1099: 		}
1100: 		return false, nil
1101: 	}
1102: 	var failure *axi.Error
1103: 	if errors.As(err, &failure) && (failure.Code == "review_round_unchanged" || failure.Code == "review_round_active") {
1104: 		return false, nil
1105: 	}
1106: 	return err == nil, err
1107: }
