// ReviewRoundAdmission binds a new Review Task to one numbered round. All
// repository bindings are inserted with the Task in the same transaction.
type ReviewRoundAdmission struct {
	ChangeTaskID       int64
	Round              int
	MaxRounds          int
	SharedRepairBudget bool
