+		request.RequestedAt = int64(100 + i*100)
+		request.SettledAt = request.RequestedAt + 50
+		request.Outcome = outcome
+		if outcome == "verdict" || i == 1 {
+			request.Grant = grant
+		}
+		if err := f.db.RecordGreenhouseReviewRequest(ctx, request); err != nil {
+			t.Fatal(err)
