23: func (db *DB) RecordGreenhouseReviewRequest(ctx context.Context, request GreenhouseReviewRequest) error {
24: 	if request.Provider != GreenhouseReviewProvider || request.TaskID < 1 || request.ProjectID < 1 || request.Repository == "" || len(request.RequestedHead) != 40 && len(request.RequestedHead) != 64 || request.RequestedAt < 1 || request.SettledAt < request.RequestedAt {
25: 		return errors.New("invalid Greenhouse review request")
26: 	}
27: 	if request.Outcome != "verdict" && request.Outcome != "refused" && request.Outcome != "failed" && request.Outcome != "head_mismatch" {
28: 		return errors.New("invalid Greenhouse review request outcome")
29: 	}
30: 	var belongs bool
31: 	if err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM tasks WHERE id=? AND project_id=?)`, request.TaskID, request.ProjectID).Scan(&belongs); err != nil {
32: 		return err
33: 	}
34: 	if !belongs {
35: 		return errors.New("greenhouse request Task does not belong to its Project")
36: 	}
37: 	var verdictID any
38: 	if request.Grant != "" {
39: 		var id int64
40: 		err := db.QueryRowContext(ctx, `SELECT id FROM verdicts WHERE grant_id=? AND task_id=? AND repo=? AND provider='greenhouse' AND mode='parallel'`, request.Grant, request.TaskID, request.Repository).Scan(&id)
41: 		if err == nil {
42: 			verdictID = id
43: 		} else if !errors.Is(err, sql.ErrNoRows) {
44: 			return err
45: 		}
