61: func reviewComparison(ctx context.Context, db *store.DB) (map[string]any, error) {
62: 	projects, err := db.Projects(ctx)
63: 	if err != nil {
64: 		return nil, err
65: 	}
66: 	globalBuiltinLatency, err := builtinReviewLatency(ctx, db, 0)
67: 	if err != nil {
68: 		return nil, err
69: 	}
70: 	var rows []reviewComparisonRow
71: 	var totalRequests, totalVerdicts, totalWrong, totalInconclusive, totalMatched, totalPairs, projectsWithReviews int
72: 	var allLatency []int64
73: 	for _, project := range projects {
74: 		row, latencies, err := reviewComparisonForProject(ctx, db, project)
75: 		if err != nil {
76: 			return nil, err
77: 		}
78: 		if row.BuiltinMedianLatencyMS == nil && globalBuiltinLatency != nil {
79: 			row.BuiltinMedianLatencyMS = globalBuiltinLatency
80: 			limit := *globalBuiltinLatency * 3 / 2
81: 			row.LatencyLimitMS = &limit
82: 			if row.MedianLatencyMS != nil {
83: 				pass := *row.MedianLatencyMS <= limit
84: 				row.LatencyPass = &pass
85: 			}
86: 		}
87: 		rows = append(rows, row)
88: 		totalRequests += row.Requests
89: 		totalVerdicts += row.Verdicts
90: 		totalWrong += row.WrongHead
91: 		totalInconclusive += row.Inconclusive
92: 		totalMatched += row.RecallMatched
93: 		totalPairs += row.RecallPairs
94: 		allLatency = append(allLatency, latencies...)
95: 		if row.ReviewedHeads > 0 {
96: 			projectsWithReviews++
97: 		}
98: 	}
99: 	total := reviewComparisonRow{Project: "total", Requests: totalRequests, Verdicts: totalVerdicts, WrongHead: totalWrong, Inconclusive: totalInconclusive, RecallMatched: totalMatched, RecallPairs: totalPairs, Precision: "not measured in G1"}
100: 	for _, row := range rows {
101: 		total.ReviewedHeads += row.ReviewedHeads
102: 		total.UnmatchedPairs = append(total.UnmatchedPairs, row.UnmatchedPairs...)
103: 	}
104: 	total.ProjectsWithReviews = projectsWithReviews
105: 	samplePass := total.ReviewedHeads >= 50 && projectsWithReviews >= 2
106: 	total.SamplePass = &samplePass
107: 	if total.Requests > 0 {
108: 		total.Reliability = float64(total.Verdicts) / float64(total.Requests)
109: 		pass := total.Reliability >= 0.95
110: 		total.ReliabilityPass = &pass
111: 	}
112: 	if total.Requests > 0 {
113: 		total.WrongHeadRate = float64(total.WrongHead) / float64(total.Requests)
114: 	}
115: 	wrongPass := total.WrongHead == 0
116: 	total.WrongHeadPass = &wrongPass
117: 	if total.Verdicts > 0 {
118: 		total.InconclusiveShare = float64(total.Inconclusive) / float64(total.Verdicts)
119: 		pass := total.InconclusiveShare <= 0.10
120: 		total.InconclusivePass = &pass
121: 	}
122: 	if total.RecallPairs > 0 {
123: 		recall := float64(total.RecallMatched) / float64(total.RecallPairs)
124: 		total.Recall = &recall
125: 		pass := recall >= 0.90
126: 		total.RecallPass = &pass
127: 	}
128: 	if len(allLatency) > 0 {
129: 		median := medianInt64(allLatency)
130: 		total.MedianLatencyMS = &median
131: 	}
132: 	if globalBuiltinLatency != nil && total.MedianLatencyMS != nil {
133: 		median := *globalBuiltinLatency
134: 		total.BuiltinMedianLatencyMS = &median
135: 		limit := median * 3 / 2
136: 		total.LatencyLimitMS = &limit
137: 		pass := *total.MedianLatencyMS <= limit
138: 		total.LatencyPass = &pass
139: 	}
140: 	return map[string]any{"projects": rows, "total": total}, nil
141: }
